	    Brand entity = addToProducts(event.getBrandId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindBrand( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
