/*
 * @param	event RemoveProductsFromBrandEvent
 */
@EventHandler( payloadType=RemoveProductsFromBrandEvent.class)
public void handle( RemoveProductsFromBrandEvent event) {
    LOGGER.info("handling RemoveProductsFromBrandEvent - " + event );

    Brand entity = removeFromProducts(event.getBrandId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindBrand( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllBrand( entity );
}



    /**
     * Method to retrieve the Brand via an BrandPrimaryKey.
     * @param 	id Long
     * @return 	Brand
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Brand handle( FindBrandQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getBrandId() );
    }
    
    /**
     * Method to retrieve a collection of all Brands
     *
     * @param	query	FindAllBrandQuery 
     * @return 	List<Brand> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Brand> handle( FindAllBrandQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindBrand,
 * but only if the id matches
 *
 * @param		entity	Brand
 */
	protected void emitFindBrand( Brand entity ) {
		LOGGER.info("handling emitFindBrand" );
		
	    queryUpdateEmitter.emit(FindBrandQuery.class,
	                            query -> query.getFilter().getBrandId().equals(entity.getBrandId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBrand
	 * 
	 * @param		entity	Brand
	 */
	protected void emitFindAllBrand( Brand entity ) {
		LOGGER.info("handling emitFindAllBrand" );
		
	    queryUpdateEmitter.emit(FindAllBrandQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
